package com.speedracersedge.gameimport android.app.AlertDialogimport android.content.Contextimport android.graphics.Canvasimport android.graphics.Colorimport android.graphics.Paintimport android.graphics.Pathimport android.graphics.Typefaceimport android.graphics.drawable.GradientDrawableimport android.view.Gravityimport android.view.Viewimport android.widget.FrameLayoutimport android.widget.LinearLayoutimport android.widget.ScrollViewimport android.widget.TextViewimport android.widget.Toastimport kotlin.math.minclass GameScreen(context: Context) : FrameLayout(context) {    private enum class Screen {        LOADING, TAP_TO_START, LOBBY, SETTINGS, CONTROLS, SHOP,        FRIENDS, PROFILE, MODE_MENU, RACE_STARTING, INFO    }    private var currentScreen = Screen.LOADING    private var loadingProgress = 0    private var selectedMode = "ONLINE RACE"    private var selectedControl = "Touch Steering"    private var playerReady = false    private var teamPlayers = 1    private var coins = 0    private var gems = 0    private var pendingInvite = false    private var pendingInviteName = "Alex"    private var shopCategory = "Cars"    private var pageButtonCount = 0    private val backgroundView = RacingBackgroundView(context)    private val content = FrameLayout(context)    init {        addView(backgroundView, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.MATCH_PARENT))        addView(content, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.MATCH_PARENT))        showLoading()    }    private fun dp(value: Int): Int = (value * resources.displayMetrics.density).toInt()    private fun frameParams(width: Int, height: Int, gravity: Int = Gravity.TOP or Gravity.START): LayoutParams =        LayoutParams(if (width == LayoutParams.MATCH_PARENT) width else dp(width), if (height == LayoutParams.MATCH_PARENT) height else dp(height), gravity)    private fun resetContent() {        content.removeAllViews()    }    private fun addBackground(showRoad: Boolean = true) {        backgroundView.showRoad = showRoad        backgroundView.invalidate()    }    private fun showLoading() {        currentScreen = Screen.LOADING        resetContent()        addBackground()        val wrapper = LinearLayout(context).apply {            orientation = LinearLayout.VERTICAL            gravity = Gravity.BOTTOM or Gravity.CENTER_HORIZONTAL            setPadding(dp(24), dp(24), dp(24), dp(42))        }        wrapper.addView(createText("SPEED RACERS EDGE", 28f, Color.WHITE, true).apply { gravity = Gravity.CENTER },            LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(44)))        wrapper.addView(createText("RACE BEYOND THE LIMIT", 12f, Color.CYAN, true).apply { gravity = Gravity.CENTER },            LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(28)))        val progressText = createText("LOADING 0%", 12f, Color.WHITE, true).apply { gravity = Gravity.CENTER }        wrapper.addView(progressText, LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(28)))        val track = FrameLayout(context).apply {            background = roundedBackground(Color.argb(170, 5, 15, 30), Color.CYAN, 1)        }        val fill = View(context).apply { background = roundedBackground(Color.CYAN, Color.TRANSPARENT, 0) }        track.addView(fill, FrameLayout.LayoutParams(0, dp(6), Gravity.START or Gravity.CENTER_VERTICAL))        wrapper.addView(track, LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(8)))        content.addView(wrapper, frameParams(LayoutParams.MATCH_PARENT, LayoutParams.MATCH_PARENT))        loadingProgress = 0        val loadingTask = object : Runnable {            override fun run() {                if (currentScreen != Screen.LOADING) return                loadingProgress = (loadingProgress + 5).coerceAtMost(100)                progressText.text = "LOADING $loadingProgress%"                val width = (track.width * loadingProgress / 100f).toInt()                fill.layoutParams = FrameLayout.LayoutParams(width, dp(6), Gravity.START or Gravity.CENTER_VERTICAL)                if (loadingProgress < 100) postDelayed(this, 90L)                else postDelayed({ if (currentScreen == Screen.LOADING) showTapToStart() }, 250L)            }        }        postDelayed(loadingTask, 250L)    }    private fun showTapToStart() {        currentScreen = Screen.TAP_TO_START        resetContent()        addBackground()        val overlay = LinearLayout(context).apply {            orientation = LinearLayout.VERTICAL            gravity = Gravity.BOTTOM or Gravity.CENTER_HORIZONTAL            setPadding(dp(20), dp(20), dp(20), dp(48))            isClickable = true            setOnClickListener { showLobby() }        }        overlay.addView(createText("SPEED RACERS EDGE", 28f, Color.WHITE, true).apply { gravity = Gravity.CENTER },            LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(48)))        overlay.addView(createText("T A P   T O   S T A R T", 15f, Color.CYAN, true).apply { gravity = Gravity.CENTER },            LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(40)))        content.addView(overlay, frameParams(LayoutParams.MATCH_PARENT, LayoutParams.MATCH_PARENT))    }    private fun showLobby() {        currentScreen = Screen.LOBBY        resetContent()        addBackground()        val root = FrameLayout(context)        content.addView(root, frameParams(LayoutParams.MATCH_PARENT, LayoutParams.MATCH_PARENT))        root.addView(createButton("ðŸ‘¤ ADAM â€¢ LV.1", 11f) { showProfile() },            frameParams(138, 42, Gravity.TOP or Gravity.START).apply { leftMargin = dp(10); topMargin = dp(10) })        val currency = LinearLayout(context).apply { orientation = LinearLayout.VERTICAL; gravity = Gravity.CENTER }        currency.addView(createText("ðŸª™ $coins", 12f, Color.WHITE, true).apply { gravity = Gravity.CENTER })        currency.addView(createText("ðŸ’Ž $gems", 12f, Color.CYAN, true).apply { gravity = Gravity.CENTER })        root.addView(currency, frameParams(95, 46, Gravity.TOP or Gravity.CENTER_HORIZONTAL).apply { topMargin = dp(7) })        root.addView(createButton("âš™ SETTINGS", 10f) { showSettings() },            frameParams(100, 42, Gravity.TOP or Gravity.END).apply { rightMargin = dp(10); topMargin = dp(10) })        root.addView(createText("WELCOME TO THE EDGE", 15f, Color.WHITE, true).apply { gravity = Gravity.CENTER },            frameParams(LayoutParams.MATCH_PARENT, 30, Gravity.TOP).apply { topMargin = dp(63) })        root.addView(createText(selectedMode, 11f, Color.CYAN, true).apply { gravity = Gravity.CENTER },            frameParams(LayoutParams.MATCH_PARENT, 24, Gravity.TOP).apply { topMargin = dp(93) })        val car = LinearLayout(context).apply {            orientation = LinearLayout.VERTICAL            gravity = Gravity.CENTER            background = roundedBackground(Color.argb(115, 4, 12, 25), Color.CYAN, 1)        }        car.addView(createText("ðŸŽï¸", 72f, Color.WHITE, false).apply { gravity = Gravity.CENTER },            LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(104)))        car.addView(createText("YOUR RIDE", 10f, Color.WHITE, true).apply { gravity = Gravity.CENTER },            LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(24)))        root.addView(car, frameParams(205, 142, Gravity.TOP or Gravity.CENTER_HORIZONTAL).apply { topMargin = dp(135) })        val team = LinearLayout(context).apply {            orientation = LinearLayout.VERTICAL            gravity = Gravity.CENTER            setPadding(dp(6), dp(6), dp(6), dp(6))            background = roundedBackground(Color.argb(225, 5, 15, 32), Color.CYAN, 1)        }        team.addView(createText("TEAM $teamPlayers/4", 12f, Color.WHITE, true).apply { gravity = Gravity.CENTER },            LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(26)))        for (i in 0..3) {            val slot = when { i == 0 -> "ðŸ‘¤ ADAM"; i < teamPlayers -> "ðŸ‘¤ MEMBER ${i + 1}"; else -> "+ OPEN SLOT" }            team.addView(createText(slot, 10f, if (i < teamPlayers) Color.WHITE else Color.LTGRAY, i == 0),                LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(27)))        }        team.addView(createButton("INVITE", 10f) { showFriends() }, LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(32)))        team.addView(createButton(if (playerReady) "READY âœ“" else "READY", 10f) {            playerReady = !playerReady            showLobby()        }, LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(32)))        root.addView(team, frameParams(136, 250, Gravity.END or Gravity.CENTER_VERTICAL).apply { rightMargin = dp(8); topMargin = dp(30) })        root.addView(createButton("SHOP", 12f) { showShop() },            frameParams(100, 46, Gravity.BOTTOM or Gravity.START).apply { leftMargin = dp(10); bottomMargin = dp(14) })        root.addView(createButton("FRIENDS", 10f) { showFriends() },            frameParams(96, 38, Gravity.BOTTOM or Gravity.CENTER_HORIZONTAL).apply { bottomMargin = dp(18) })        root.addView(createButton("SELECT MODE", 11f) { showModeMenu() },            frameParams(128, 46, Gravity.BOTTOM or Gravity.END).apply { rightMargin = dp(10); bottomMargin = dp(14) })        if (pendingInvite) showInvitePopup(root)    }    private fun showSettings() {        currentScreen = Screen.SETTINGS        resetContent(); addBackground(false)        val root = makePage("SETTINGS")        pageButtonCount = 0        addPageButton(root, "Gameplay") { showInfoPage("GAMEPLAY", "Gameplay options will be connected as the racing systems are implemented.") }        addPageButton(root, "Controls") { showControls() }        addPageButton(root, "Graphics") { showInfoPage("GRAPHICS", "Graphics presets will be connected when the 3D renderer is ready.") }        addPageButton(root, "Sound") { showInfoPage("SOUND", "Sound settings are not connected yet.") }        addPageButton(root, "Language") { showInfoPage("LANGUAGE", "Language selection will be added here.") }        addPageButton(root, "Account") { showInfoPage("ACCOUNT", "Account sign-in and cloud saving are not connected yet.") }        addPageButton(root, "About") { showInfoPage("ABOUT", "Speed Racers Edge is an Android racing game in development.") }        addBackButton(root)    }    private fun showControls() {        currentScreen = Screen.CONTROLS        resetContent(); addBackground(false)        val root = makePage("CONTROLS")        root.addView(createText("Choose your preferred steering method.", 13f, Color.WHITE, false),            frameParams(LayoutParams.MATCH_PARENT, 42).apply { topMargin = dp(68); leftMargin = dp(12) })        listOf("Tilt", "Steering Wheel", "Arrow Buttons", "Touch Steering").forEachIndexed { index, option ->            root.addView(createButton((if (selectedControl == option) "âœ“  " else "") + option, 13f) {                selectedControl = option; showControls()            }, frameParams(LayoutParams.MATCH_PARENT, 48).apply {                topMargin = dp(118 + index * 57); leftMargin = dp(12); rightMargin = dp(12)            })        }        addBackButton(root)    }    private fun showShop() {        currentScreen = Screen.SHOP        resetContent(); addBackground(false)        val root = makePage("SHOP")        root.addView(createText("ðŸª™ $coins Race Coins     ðŸ’Ž $gems Gems", 13f, Color.WHITE, true).apply { gravity = Gravity.CENTER },            frameParams(LayoutParams.MATCH_PARENT, 34).apply { topMargin = dp(64) })        val scroll = ScrollView(context)        val list = LinearLayout(context).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(12), dp(8), dp(12), dp(12)) }        listOf("Cars", "Drivers", "Car Skins", "Vehicle Effects", "Emotes", "Arrival & Finish Effects", "Coins", "Gems").forEach { category ->            list.addView(createButton((if (shopCategory == category) "âœ“  " else "") + category, 12f) {                shopCategory = category; showShop()            }, LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(42)).apply { bottomMargin = dp(6) })        }        val description = when (shopCategory) {            "Coins" -> "Race Coins are earned through gameplay."            "Gems" -> "Premium Gems will require a connected purchase system."            else -> "$shopCategory will contain unlockable items as the shop is developed."        }        list.addView(createText(description, 12f, Color.WHITE, false).apply { gravity = Gravity.CENTER },            LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(60)))        scroll.addView(list)        root.addView(scroll, frameParams(LayoutParams.MATCH_PARENT, LayoutParams.MATCH_PARENT).apply {            topMargin = dp(104); bottomMargin = dp(60)        })        addBackButton(root)    }    private fun showFriends() {        currentScreen = Screen.FRIENDS        resetContent(); addBackground(false)        val root = makePage("FRIENDS & TEAM")        root.addView(createText("Invite friends to your team. Maximum team size: 4.", 12f, Color.WHITE, false),            frameParams(LayoutParams.MATCH_PARENT, 44).apply { topMargin = dp(64); leftMargin = dp(12); rightMargin = dp(12) })        listOf("Alex â€¢ ONLINE", "Mike â€¢ ONLINE", "John â€¢ OFFLINE").forEachIndexed { index, name ->            val online = name.contains("ONLINE")            root.addView(createButton("ðŸ‘¤ $name   ${if (online) "INVITE" else "OFFLINE"}", 11f) {                if (!online) {                    Toast.makeText(context, "This friend is offline.", Toast.LENGTH_SHORT).show()                } else if (teamPlayers >= 4) {                    Toast.makeText(context, "Your team is full.", Toast.LENGTH_SHORT).show()                } else {                    showInviteConfirmation(name.substringBefore(" â€¢"))                }            }, frameParams(LayoutParams.MATCH_PARENT, 48).apply {                topMargin = dp(116 + index * 58); leftMargin = dp(12); rightMargin = dp(12)            })        }        addBackButton(root)    }    private fun showInviteConfirmation(friendName: String) {        AlertDialog.Builder(context)            .setTitle("Invite $friendName?")            .setMessage("This is a local interface preview. Cross-device team invitations require an online backend.")            .setNegativeButton("CANCEL", null)            .setPositiveButton("INVITE") { _, _ ->                if (teamPlayers < 4) teamPlayers++                Toast.makeText(context, "Local invite preview sent to $friendName.", Toast.LENGTH_SHORT).show()                showLobby()            }            .show()    }    private fun showInvitePopup(root: FrameLayout) {        val popup = LinearLayout(context).apply {            orientation = LinearLayout.VERTICAL            setPadding(dp(10), dp(8), dp(10), dp(8))            background = roundedBackground(Color.rgb(8, 20, 40), Color.CYAN, 2)        }        popup.addView(createText("TEAM INVITATION", 11f, Color.CYAN, true),            LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(24)))        popup.addView(createText("$pendingInviteName invited you to join their team.", 10f, Color.WHITE, false),            LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(38)))        val actions = LinearLayout(context).apply { orientation = LinearLayout.HORIZONTAL }        actions.addView(createButton("ACCEPT", 9f) {            pendingInvite = false            if (teamPlayers < 4) teamPlayers++            showLobby()            Toast.makeText(context, "Accepted in local preview.", Toast.LENGTH_SHORT).show()        }, LinearLayout.LayoutParams(0, dp(32), 1f))        actions.addView(createButton("DECLINE", 9f) { pendingInvite = false; showLobby() },            LinearLayout.LayoutParams(0, dp(32), 1f))        popup.addView(actions)        root.addView(popup, frameParams(230, 112, Gravity.TOP or Gravity.END).apply { topMargin = dp(60); rightMargin = dp(10) })    }    private fun showProfile() {        currentScreen = Screen.PROFILE        resetContent(); addBackground(false)        val root = makePage("PLAYER PROFILE")        root.addView(createText("ðŸ‘¤", 58f, Color.WHITE, false).apply { gravity = Gravity.CENTER },            frameParams(LayoutParams.MATCH_PARENT, 90).apply { topMargin = dp(74) })        root.addView(createText("ADAM", 22f, Color.WHITE, true).apply { gravity = Gravity.CENTER },            frameParams(LayoutParams.MATCH_PARENT, 42).apply { topMargin = dp(164) })        root.addView(createText("LEVEL 1\nRace Coins: $coins\nGems: $gems", 14f, Color.WHITE, false).apply { gravity = Gravity.CENTER },            frameParams(LayoutParams.MATCH_PARENT, 100).apply { topMargin = dp(210) })        addBackButton(root)    }    private fun showModeMenu() {        currentScreen = Screen.MODE_MENU        resetContent(); addBackground(false)        val root = makePage("SELECT MODE")        listOf("QUICK RACE", "ONLINE RACE", "HEIST", "PRIVATE LOBBY", "SPECIAL EVENTS").forEachIndexed { index, mode ->            root.addView(createButton((if (selectedMode == mode) "âœ“  " else "") + mode, 12f) {                selectedMode = mode; showModeMenu()            }, frameParams(LayoutParams.MATCH_PARENT, 47).apply {                topMargin = dp(72 + index * 54); leftMargin = dp(12); rightMargin = dp(12)            })        }        root.addView(createButton("CONTINUE", 12f) { showRaceStarting() },            frameParams(LayoutParams.MATCH_PARENT, 46, Gravity.BOTTOM).apply {                bottomMargin = dp(64); leftMargin = dp(12); rightMargin = dp(12)            })        addBackButton(root)    }    private fun showRaceStarting() {        currentScreen = Screen.RACE_STARTING        resetContent(); addBackground()        val panel = LinearLayout(context).apply {            orientation = LinearLayout.VERTICAL; gravity = Gravity.CENTER            setPadding(dp(18), dp(18), dp(18), dp(18))            background = roundedBackground(Color.argb(230, 5, 15, 32), Color.CYAN, 2)        }        panel.addView(createText("RACE READY", 23f, Color.WHITE, true).apply { gravity = Gravity.CENTER },            LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(44)))        panel.addView(createText("MODE: $selectedMode", 13f, Color.CYAN, true).apply { gravity = Gravity.CENTER },            LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(36)))        panel.addView(createText("This build is a UI preview. Racing, matchmaking and online gameplay are not connected yet.", 12f, Color.WHITE, false).apply { gravity = Gravity.CENTER },            LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(84)))        panel.addView(createButton("BACK TO LOBBY", 12f) { showLobby() },            LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(42)))        content.addView(panel, frameParams(300, 250, Gravity.CENTER))    }    private fun showInfoPage(title: String, message: String) {        currentScreen = Screen.INFO        resetContent(); addBackground(false)        val root = makePage(title)        root.addView(createText(message, 14f, Color.WHITE, false).apply {            gravity = Gravity.CENTER; setPadding(dp(20), dp(10), dp(20), dp(10))        }, frameParams(LayoutParams.MATCH_PARENT, 180, Gravity.CENTER))        addBackButton(root)    }    private fun makePage(title: String): FrameLayout {        val root = FrameLayout(context)        content.addView(root, frameParams(LayoutParams.MATCH_PARENT, LayoutParams.MATCH_PARENT))        val heading = createText(title, 20f, Color.WHITE, true).apply {            gravity = Gravity.CENTER            background = roundedBackground(Color.argb(220, 5, 15, 32), Color.CYAN, 1)        }        root.addView(heading, frameParams(LayoutParams.MATCH_PARENT, 46).apply {            leftMargin = dp(12); rightMargin = dp(12); topMargin = dp(10)        })        return root    }    private fun addPageButton(root: FrameLayout, label: String, action: () -> Unit) {        val index = pageButtonCount++        root.addView(createButton(label, 13f, action), frameParams(LayoutParams.MATCH_PARENT, 47).apply {            topMargin = dp(70 + index * 54); leftMargin = dp(12); rightMargin = dp(12)        })    }    private fun addBackButton(root: FrameLayout) {        root.addView(createButton("â† BACK", 11f) {            pageButtonCount = 0            showLobby()        }, frameParams(105, 40, Gravity.BOTTOM or Gravity.START).apply {            leftMargin = dp(12); bottomMargin = dp(12)        })    }    private fun createText(value: String, size: Float, color: Int, bold: Boolean): TextView = TextView(context).apply {        text = value        textSize = size        setTextColor(color)        gravity = Gravity.CENTER_VERTICAL        typeface = Typeface.create("sans-serif", if (bold) Typeface.BOLD else Typeface.NORMAL)        setPadding(dp(4), dp(2), dp(4), dp(2))    }    private fun createButton(label: String, size: Float = 13f, action: () -> Unit): TextView = TextView(context).apply {        text = label        textSize = size        typeface = Typeface.create("sans-serif", Typeface.BOLD)        setTextColor(Color.WHITE)        gravity = Gravity.CENTER        isClickable = true        isFocusable = true        setPadding(dp(5), dp(4), dp(5), dp(4))        background = roundedBackground(Color.argb(225, 5, 19, 38), Color.CYAN, 1)        setOnClickListener { action() }    }    private fun roundedBackground(fillColor: Int, strokeColor: Int, strokeWidth: Int): GradientDrawable =        GradientDrawable().apply {            shape = GradientDrawable.RECTANGLE            cornerRadius = dp(9).toFloat()            setColor(fillColor)            if (strokeWidth > 0) setStroke(dp(strokeWidth), strokeColor)        }    private inner class RacingBackgroundView(context: Context) : View(context) {        var showRoad: Boolean = true        private val paint = Paint(Paint.ANTI_ALIAS_FLAG)        override fun onDraw(canvas: Canvas) {            super.onDraw(canvas)            val w = width.toFloat()            val h = height.toFloat()            if (w <= 0f || h <= 0f) return            val skyPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {                shader = android.graphics.LinearGradient(                    0f, 0f, 0f, h,                    Color.rgb(3, 8, 23), Color.rgb(8, 35, 58),                    android.graphics.Shader.TileMode.CLAMP                )            }            canvas.drawRect(0f, 0f, w, h, skyPaint)            val buildingWidth = w / 9f            val buildingPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply { color = Color.rgb(5, 13, 28) }            val windowPaint = Paint(Paint.ANTI_ALIAS_FLAG)            for (i in 0..9) {                val left = i * buildingWidth - buildingWidth * 0.15f                val buildingHeight = h * (0.13f + ((i * 37) % 20) / 100f)                val top = h * 0.38f - buildingHeight * 0.35f                canvas.drawRect(left, top, left + buildingWidth, h * 0.62f, buildingPaint)                for (row in 0..5) for (col in 0..2) {                    val x = left + buildingWidth * (0.2f + col * 0.25f)                    val y = top + dp(8) + row * dp(13)                    windowPaint.color = when ((i + row + col) % 4) {                        0 -> Color.argb(190, 40, 190, 255)                        1 -> Color.argb(170, 255, 80, 90)                        else -> Color.argb(100, 55, 120, 160)                    }                    canvas.drawRect(x, y, x + dp(3), y + dp(5), windowPaint)                }            }            paint.color = Color.rgb(4, 24, 43)            canvas.drawRect(0f, h * 0.56f, w, h * 0.83f, paint)            for (i in 0..30) {                val y = h * 0.58f + i * h * 0.007f                val half = w * (0.08f + i * 0.019f)                paint.color = if (i % 3 == 0) Color.argb(100, 45, 185, 255) else Color.argb(45, 40, 105, 160)                canvas.drawRect(w / 2f - half, y, w / 2f + half, y + dp(2), paint)            }            val bridge = Path().apply {                moveTo(0f, h * 0.60f)                lineTo(w * 0.18f, h * 0.51f)                lineTo(w * 0.82f, h * 0.51f)                lineTo(w, h * 0.60f)                lineTo(w, h * 0.64f)                lineTo(0f, h * 0.64f)                close()            }            paint.color = Color.rgb(12, 26, 43)            canvas.drawPath(bridge, paint)            paint.color = Color.rgb(42, 190, 240)            paint.strokeWidth = dp(2).toFloat()            paint.style = Paint.Style.STROKE            canvas.drawLine(0f, h * 0.60f, w, h * 0.60f, paint)            paint.style = Paint.Style.FILL            if (showRoad) {                val road = Path().apply {                    moveTo(w * 0.43f, h * 0.57f)                    lineTo(w * 0.57f, h * 0.57f)                    lineTo(w * 1.1f, h)                    lineTo(w * -0.1f, h)                    close()                }                paint.color = Color.rgb(8, 12, 22)                canvas.drawPath(road, paint)                paint.color = Color.rgb(220, 45, 65)                paint.strokeWidth = dp(2).toFloat()                canvas.drawLine(w * 0.43f, h * 0.57f, w * 0.08f, h, paint)                paint.color = Color.rgb(40, 205, 255)                canvas.drawLine(w * 0.57f, h * 0.57f, w * 0.92f, h, paint)                paint.color = Color.argb(180, 150, 190, 210)                for (i in 0..5) {                    val f = i / 5f                    val y = h * (0.61f + f * 0.36f)                    val half = w * (0.015f + f * 0.25f)                    canvas.drawRect(w / 2f - half, y, w / 2f + half, y + dp(2), paint)                }            }            paint.style = Paint.Style.FILL            paint.shader = android.graphics.RadialGradient(                w / 2f, h / 2f, min(w, h) * 0.8f,                intArrayOf(Color.TRANSPARENT, Color.argb(150, 0, 0, 0)), null,                android.graphics.Shader.TileMode.CLAMP            )            canvas.drawRect(0f, 0f, w, h, paint)            paint.shader = null        }    } } 